CREATE SCHEMA IF NOT EXISTS bugflow;
CREATE TABLE bugflow.users (id uuid PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bugflow.projects (id uuid PRIMARY KEY, name text NOT NULL, description text NOT NULL DEFAULT '', environment text NOT NULL DEFAULT 'Development', archived boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bugflow.modules (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES bugflow.projects(id), name text NOT NULL, UNIQUE(project_id,name));
CREATE TABLE bugflow.portals (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES bugflow.users(id), type text NOT NULL CHECK(type IN ('admin','reporter','qa','developer','member')), token_hash text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true, expires_at timestamptz, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bugflow.portal_projects (portal_id uuid NOT NULL REFERENCES bugflow.portals(id), project_id uuid NOT NULL REFERENCES bugflow.projects(id), PRIMARY KEY(portal_id,project_id));
CREATE SEQUENCE bugflow.bug_number;
CREATE TABLE bugflow.bugs (id bigint PRIMARY KEY DEFAULT nextval('bugflow.bug_number'), title text NOT NULL, project_id uuid NOT NULL REFERENCES bugflow.projects(id), module_id uuid REFERENCES bugflow.modules(id), reporter_id uuid NOT NULL REFERENCES bugflow.users(id), qa_owner_id uuid REFERENCES bugflow.users(id), assignee_id uuid REFERENCES bugflow.users(id), status text NOT NULL DEFAULT 'NEW' CHECK(status IN ('NEW','VALIDATING','VALIDATED','READY_FOR_ASSIGNMENT','ASSIGNED','IN_PROGRESS','RECHECK','RESOLVED','NEEDS_INFORMATION','REOPENED','DUPLICATE','NOT_A_BUG','WONT_FIX')), priority text NOT NULL DEFAULT 'Medium', severity text NOT NULL DEFAULT 'Medium', description text NOT NULL, expected text NOT NULL, actual text NOT NULL, browser_device text NOT NULL DEFAULT '', environment text NOT NULL DEFAULT 'Development', fix_notes text NOT NULL DEFAULT '', duplicate_of bigint REFERENCES bugflow.bugs(id), due_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bugflow.steps (bug_id bigint NOT NULL REFERENCES bugflow.bugs(id), position integer NOT NULL CHECK(position>0), content text NOT NULL, PRIMARY KEY(bug_id,position));
CREATE TABLE bugflow.comments (id uuid PRIMARY KEY, bug_id bigint NOT NULL REFERENCES bugflow.bugs(id), actor_id uuid NOT NULL REFERENCES bugflow.users(id), content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bugflow.assignment_batches (id uuid PRIMARY KEY, actor_id uuid NOT NULL REFERENCES bugflow.users(id), confirmed_bug_ids jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bugflow.assignments (id uuid PRIMARY KEY, bug_id bigint NOT NULL REFERENCES bugflow.bugs(id), actor_id uuid NOT NULL REFERENCES bugflow.users(id), previous_assignee_id uuid REFERENCES bugflow.users(id), assignee_id uuid NOT NULL REFERENCES bugflow.users(id), batch_id uuid REFERENCES bugflow.assignment_batches(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bugflow.status_history (id uuid PRIMARY KEY, bug_id bigint NOT NULL REFERENCES bugflow.bugs(id), actor_id uuid NOT NULL REFERENCES bugflow.users(id), previous_status text, new_status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bugflow.verifications (id uuid PRIMARY KEY, bug_id bigint NOT NULL REFERENCES bugflow.bugs(id), actor_id uuid NOT NULL REFERENCES bugflow.users(id), passed boolean NOT NULL, notes text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bugflow.evidence (id uuid PRIMARY KEY, bug_id bigint NOT NULL REFERENCES bugflow.bugs(id), uploaded_by uuid NOT NULL REFERENCES bugflow.users(id), object_key text NOT NULL UNIQUE, filename text NOT NULL, mime_type text NOT NULL, byte_size bigint NOT NULL CHECK(byte_size>0), state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','ready','deleting','deleted')), deleted_by uuid REFERENCES bugflow.users(id), deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bugflow.activity (id uuid PRIMARY KEY, actor_id uuid NOT NULL REFERENCES bugflow.users(id), bug_id bigint REFERENCES bugflow.bugs(id), action text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bugflow.saved_views (id uuid PRIMARY KEY, portal_id uuid NOT NULL REFERENCES bugflow.portals(id), name text NOT NULL, filters jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bugflow.settings (key text PRIMARY KEY, value jsonb NOT NULL);
CREATE INDEX bugs_updated ON bugflow.bugs(updated_at DESC,id DESC);
CREATE INDEX bugs_scope_status ON bugflow.bugs(project_id,status,id);
CREATE INDEX bugs_assignee ON bugflow.bugs(assignee_id,status,id);
CREATE INDEX bugs_reporter ON bugflow.bugs(reporter_id,id);
CREATE INDEX activity_bug ON bugflow.activity(bug_id,created_at DESC);
CREATE INDEX portals_user ON bugflow.portals(user_id,type);
CREATE INDEX evidence_bug ON bugflow.evidence(bug_id,state);
